$(cat graphify-out/.graphify_python) -c "
import json
from pathlib import Path

detect = json.loads(Path('graphify-out/.graphify_detect.json').read_text(encoding='utf-8'))
uncached = Path('graphify-out/.graphify_uncached.txt').read_text().strip().split('\n') if Path('graphify-out/.graphify_uncached.txt').exists() else []
uncached = [f for f in uncached if f.strip()]

# Group by parent dir, then create chunks of 22
from collections import defaultdict
by_dir = defaultdict(list)
for f in uncached:
    p = Path(f)
    if len(p.parts) > 2:
        key = p.parts[-3] + '/' + p.parts[-2]
    else:
        key = str(p.parent)
    by_dir[key].append(f)

docs, imgs = [], []
for f in uncached:
    if f.endswith(('.png','.jpg','.jpeg','.webp','.gif','.svg','.bmp')):
        imgs.append(f)
    else:
        docs.append(f)

chunks = []
current = []
for key in sorted(by_dir.keys()):
    for f in by_dir[key]:
        if f in imgs:
            if current:
                chunks.append(current)
                current = []
            chunks.append([f])
        else:
            if len(current) >= 22:
                chunks.append(current)
                current = []
            current.append(f)
if current:
    chunks.append(current)

Path('graphify-out/.graphify_chunks.json').write_text(json.dumps(chunks, ensure_ascii=False), encoding='utf-8')
print(f'{len(chunks)} chunks created')
"

