75	function makeProfileSchema(t: (key: string) => string) {
76	  const baseProfileSchema = z.object({
77	    name: z.string().min(1, t('profileForm.validation.nameRequired')).max(100),
78	    description: z.string().max(500).optional(),
79	    language: z.enum(LANGUAGE_CODES as [LanguageCode, ...LanguageCode[]]),
80	    personality: z.string().max(2000).optional(),
81	    sampleFile: z.instanceof(File).optional(),
82	    referenceText: z.string().max(1000).optional(),
83	    avatarFile: z.instanceof(File).optional(),
84	  });
85	
86	  return baseProfileSchema.refine(
87	    (data) => {
88	      if (data.sampleFile && (!data.referenceText || data.referenceText.trim().length === 0)) {
89	        return false;
90	      }
91	      return true;
92	    },
93	    {
94	      message: t('profileForm.validation.referenceRequired'),
95	      path: ['referenceText'],
96	    },
97	  );
98	}
