110	// Helper to convert File to base64
111	async function fileToBase64(file: File): Promise<string> {
112	  return new Promise((resolve, reject) => {
113	    const reader = new FileReader();
114	    reader.onload = () => resolve(reader.result as string);
115	    reader.onerror = reject;
116	    reader.readAsDataURL(file);
117	  });
118	}
