120	// Helper to convert base64 to File
121	function base64ToFile(base64: string, fileName: string, fileType: string): File {
122	  const arr = base64.split(',');
123	  const bstr = atob(arr[1]);
124	  let n = bstr.length;
125	  const u8arr = new Uint8Array(n);
126	  while (n--) {
127	    u8arr[n] = bstr.charCodeAt(n);
128	  }
129	  return new File([u8arr], fileName, { type: fileType });
130	}
