import { Mic, Play, Square } from 'lucide-react';
import { useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import { Textarea } from '@/components/ui/textarea';
import { useToast } from '@/components/ui/use-toast';
import { apiClient } from '@/lib/api/client';
import { formatAudioDuration } from '@/lib/utils/audio';

interface VoicePreviewProps {
  /** Profile ID — used when editing an existing saved profile */
  profileId?: string;
  /** Sample file — used when creating a new profile (no saved profile yet) */
  sampleFile?: File;
  referenceText?: string;
  language?: string;
  engine?: string;
  modelSize?: string;
}

const DEFAULT_PREVIEW_TEXT =
  "Hello! This is a preview of your cloned voice. Does it sound natural to you?";

export function VoicePreview({
  profileId,
  sampleFile,
  referenceText,
  language = 'en',
  engine = 'qwen',
  modelSize = '1.7B',
}: VoicePreviewProps) {
  const { t } = useTranslation();
  const { toast } = useToast();
  const [previewText, setPreviewText] = useState(DEFAULT_PREVIEW_TEXT);
  const [isGenerating, setIsGenerating] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const previousUrlRef = useRef<string | null>(null);

  const stopPlayback = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current = null;
    }
    if (previousUrlRef.current) {
      URL.revokeObjectURL(previousUrlRef.current);
      previousUrlRef.current = null;
    }
    setAudioUrl(null);
    setIsPlaying(false);
    setCurrentTime(0);
    setDuration(0);
  };

  const handleGenerate = async () => {
    if (!previewText.trim()) {
      toast({
        title: t('voicePreview.noText'),
        description: t('voicePreview.noTextDescription'),
        variant: 'destructive',
      });
      return;
    }

    stopPlayback();
    setIsGenerating(true);

    try {
      let blob: Blob;

      if (profileId) {
        // Existing profile — use the profile preview endpoint
        blob = await apiClient.previewProfileVoice(profileId, {
          text: previewText,
          engine,
          model_size: modelSize,
          language,
        });
      } else if (sampleFile && referenceText) {
        // New profile being created — use direct preview endpoint
        blob = await apiClient.previewDirect(sampleFile, referenceText, {
          engine,
          language,
          modelSize,
        });
      } else {
        toast({
          title: t('voicePreview.noSample'),
          description: t('voicePreview.noSampleDescription'),
          variant: 'destructive',
        });
        setIsGenerating(false);
        return;
      }

      const url = URL.createObjectURL(blob);
      previousUrlRef.current = url;
      setAudioUrl(url);

      const audio = new Audio(url);
      audioRef.current = audio;

      audio.addEventListener('loadedmetadata', () => setDuration(audio.duration));
      audio.addEventListener('timeupdate', () => setCurrentTime(audio.currentTime));
      audio.addEventListener('ended', () => {
        setIsPlaying(false);
        setCurrentTime(0);
      });
      audio.addEventListener('play', () => setIsPlaying(true));
      audio.addEventListener('pause', () => setIsPlaying(false));

      await audio.play();
    } catch (err) {
      const msg = err instanceof Error ? err.message : t('voicePreview.failed');
      toast({
        title: t('voicePreview.failed'),
        description: msg,
        variant: 'destructive',
      });
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePlayPause = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
  };

  const handleStop = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
    setIsPlaying(false);
    setCurrentTime(0);
  };

  const handleSeek = (value: number[]) => {
    if (!audioRef.current || duration === 0) return;
    audioRef.current.currentTime = (value[0] / 100) * duration;
  };

  return (
    <div className="border border-primary/20 rounded-lg bg-primary/5 p-4 space-y-3">
      <div className="flex items-center gap-2">
        <Mic className="h-4 w-4 text-primary" />
        <span className="text-sm font-medium">{t('voicePreview.title')}</span>
      </div>

      <Textarea
        value={previewText}
        onChange={(e) => setPreviewText(e.target.value)}
        placeholder={t('voicePreview.placeholder')}
        className="min-h-[80px] text-sm resize-none"
        disabled={isGenerating}
      />

      <div className="flex gap-2 items-center">
        <Button
          onClick={handleGenerate}
          disabled={isGenerating || !previewText.trim()}
          size="sm"
          className="flex items-center gap-1.5"
        >
          {isGenerating ? (
            <>
              <span className="h-3 w-3 rounded-full border-2 border-current border-t-transparent animate-spin" />
              {t('voicePreview.generating')}
            </>
          ) : (
            <>
              <Play className="h-3 w-3" />
              {t('voicePreview.generate')}
            </>
          )}
        </Button>

        {audioUrl && (
          <>
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8 shrink-0"
              onClick={handlePlayPause}
              aria-label={isPlaying ? t('voicePreview.pause') : t('voicePreview.play')}
            >
              {isPlaying ? (
                <Square className="h-2.5 w-2.5 fill-current" />
              ) : (
                <Play className="h-3 w-3" />
              )}
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 shrink-0"
              onClick={handleStop}
              aria-label={t('voicePreview.stop')}
            >
              <Square className="h-3 w-3 fill-current" />
            </Button>
          </>
        )}
      </div>

      {audioUrl && (
        <div className="space-y-1">
          <Slider
            value={duration > 0 ? [(currentTime / duration) * 100] : [0]}
            onValueChange={handleSeek}
            max={100}
            step={0.1}
            className="w-full"
            disabled={isGenerating}
          />
          <div className="flex justify-between text-xs text-muted-foreground">
            <span className="font-mono">{formatAudioDuration(currentTime)}</span>
            <span className="font-mono">{formatAudioDuration(duration)}</span>
          </div>
        </div>
      )}
    </div>
  );
}

