// Voice preview
async previewProfileVoice(
  profileId: string,
  data: {
    text: string;
    engine?: string;
    model_size?: string;
    language?: string;
    seed?: number;
    instruct?: string;
  },
): Promise<Blob> {
  const url = `${this.getBaseUrl()}/profiles/${profileId}/preview`;
  const response = await fetch(url, {
    method: 'POST',
    body: JSON.stringify(data),
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({
      detail: response.statusText,
    }));
    throw new Error(formatErrorDetail(error.detail, `HTTP error! status: ${response.status}`));
  }

  return response.blob();
}

